"use client";
import React, { createContext, useContext, useEffect, useState, ReactNode } from "react";
import { loginUser, getProfile, LoginResponse, AuthUser } from "@/lib/api/users";

interface AuthContextValue {
  user: AuthUser | null;
  token: string | null;
  loading: boolean;
  login: (email: string, password: string) => Promise<void>;
  logout: () => void;
  refreshProfile: () => Promise<void>;
}

const AuthContext = createContext<AuthContextValue | undefined>(undefined);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [token, setToken] = useState<string | null>(null);
  const [loading, setLoading] = useState<boolean>(true);

  useEffect(() => {
    const stored = typeof window !== "undefined" ? localStorage.getItem("authToken") : null;
    if (stored) {
      setToken(stored);
      getProfile()
        .then(setUser)
        .catch(() => {})
        .finally(() => setLoading(false));
    } else {
      setLoading(false);
    }
  }, []);

  async function login(email: string, password: string) {
    setLoading(true);
    try {
      const data: LoginResponse = await loginUser({ email, password });
      localStorage.setItem("authToken", data.token);
      setToken(data.token);
      setUser(data.user);
    } finally {
      setLoading(false);
    }
  }

  function logout() {
    localStorage.removeItem("authToken");
    setToken(null);
    setUser(null);
  }

  async function refreshProfile() {
    if (!token) return;
    try {
      const profile = await getProfile();
      setUser(profile);
    } catch (_) {
      // if failed, keep existing state
    }
  }

  const value: AuthContextValue = { user, token, loading, login, logout, refreshProfile };
  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error("useAuth must be used within AuthProvider");
  return ctx;
}
